<?php
$role = $this->session->userdata('permissao');
$clientEscape = function ($value) {
    return html_escape(html_entity_decode((string) $value, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
};
$clientDate = function ($value) {
    return $value && strtotime($value) ? date('d/m/Y', strtotime($value)) : 'Não informada';
};
$canOrders = $this->permission->checkPermission($role, 'vOs');
$canSales = $this->permission->checkPermission($role, 'vVenda');
?>
<section class="ui-page" aria-labelledby="client-detail-title">
<header class="ui-page-header"><div><p class="ui-eyebrow"><?= $result->fornecedor ? 'FORNECEDOR' : 'CLIENTE' ?> #<?= (int) $result->idClientes ?></p><h1 id="client-detail-title"><?= $clientEscape($result->nomeCliente) ?></h1><p>Dados do cadastro, equipamentos e histórico comercial.</p></div><div class="ui-row-actions"><?php if ($this->permission->checkPermission($role, 'eCliente')) { ?><a class="ui-button ui-button-primary" href="<?= site_url('clientes/editar/' . (int) $result->idClientes) ?>">Editar cadastro</a><?php } ?><a class="ui-button" href="<?= site_url('clientes') ?>">Voltar aos clientes</a></div></header>
<nav class="ui-section-nav" aria-label="Seções do cliente"><a class="ui-button ui-button-small" href="#tab1">Dados e contatos</a><a class="ui-button ui-button-small" href="#client-equipment">Equipamentos</a><?php if ($canOrders) { ?><a class="ui-button ui-button-small" href="#tab2">Ordens de serviço</a><?php } ?><?php if ($canSales) { ?><a class="ui-button ui-button-small" href="#tab3">Vendas</a><?php } ?></nav>
<div class="ui-card" id="tab1"><h2>Dados e contatos</h2><dl class="ui-detail-grid">
<?php foreach (['documento' => 'CPF/CNPJ', 'contato' => 'Pessoa de contato', 'telefone' => 'Telefone', 'celular' => 'Celular', 'email' => 'E-mail'] as $field => $label) { ?><div><dt><?= html_escape($label) ?></dt><dd><?= $clientEscape($result->$field ?: 'Não informado') ?></dd></div><?php } ?><div><dt>Cadastro desde</dt><dd><?= html_escape($clientDate($result->dataCadastro)) ?></dd></div></dl>
<details class="ui-disclosure ui-card-following"><summary>Endereço</summary><dl class="ui-detail-grid ui-card-following"><?php foreach (['rua' => 'Rua', 'numero' => 'Número', 'complemento' => 'Complemento', 'bairro' => 'Bairro', 'cidade' => 'Cidade', 'estado' => 'Estado', 'cep' => 'CEP'] as $field => $label) { ?><div><dt><?= html_escape($label) ?></dt><dd><?= $clientEscape($result->$field ?: 'Não informado') ?></dd></div><?php } ?></dl></details></div>
<details class="ui-card ui-disclosure ui-card-following" id="client-equipment" open><summary>Equipamentos do cliente</summary><div class="ui-section-content"><div class="ui-row-actions"><?php if ($this->permission->checkPermission($role, 'aCliente')) { ?><a class="ui-button ui-button-primary" href="<?= site_url('equipamentos/salvar') . '?cliente=' . (int) $result->idClientes ?>">Cadastrar equipamento deste cliente</a><?php } ?><a class="ui-button" href="<?= site_url('equipamentos') . '?cliente=' . (int) $result->idClientes ?>">Consultar todos os equipamentos</a></div><p class="ui-hint">Até 30 equipamentos recentes. O cadastro não confirma o recebimento físico.</p>
<div class="ui-table-scroll" role="region" aria-label="Equipamentos do cliente" tabindex="0"><table class="ui-table ui-history-table"><caption class="ui-sr-only">Equipamentos do cliente</caption><thead><tr><th scope="col">Equipamento</th><th scope="col">Modelo</th><th scope="col">Número de série</th><th scope="col">Ações</th></tr></thead><tbody><?php foreach (array_slice($equipmentRows, 0, 30) as $item) { ?><tr><td><?= html_escape($item->equipamento) ?><small>#<?= (int) $item->idEquipamentos ?></small></td><td><?= html_escape($item->modelo ?: 'Não informado') ?></td><td><?= html_escape($item->num_serie ?: 'Não informado') ?></td><td><a class="ui-button ui-button-small" href="<?= site_url('equipamentos/visualizar/' . (int) $item->idEquipamentos) ?>">Ver equipamento #<?= (int) $item->idEquipamentos ?></a></td></tr><?php } ?><?php if (! $equipmentRows) { ?><tr><td colspan="4" class="ui-empty">Nenhum equipamento cadastrado para este cliente.</td></tr><?php } ?></tbody></table></div><?php if (count($equipmentRows) > 30) { ?><p class="ui-hint">Há mais equipamentos. Use “Consultar todos os equipamentos” para continuar.</p><?php } ?></div></details>
<?php if ($canOrders) { ?><details class="ui-card ui-disclosure ui-card-following" id="tab2" open><summary>Ordens de serviço</summary><div class="ui-section-content"><p class="ui-table-hint">Deslize a tabela para consultar todos os dados e ações.</p><div class="ui-table-scroll" role="region" aria-label="Ordens de serviço do cliente" tabindex="0"><table class="ui-table ui-history-table"><caption class="ui-sr-only">Ordens de serviço do cliente</caption><thead><tr><th scope="col">OS</th><th scope="col">Abertura</th><th scope="col">Situação</th><th scope="col">Equipamento / descrição</th><th scope="col">Ações</th></tr></thead><tbody><?php foreach ($results as $order) { ?><tr><td>#<?= (int) $order->idOs ?></td><td><?= html_escape($clientDate($order->dataInicial)) ?><small>Data final: <?= html_escape($clientDate($order->dataFinal)) ?></small></td><td><span class="ui-badge"><?= html_escape($order->status) ?></span></td><td><?= $clientEscape(trim(strip_tags((string) $order->descricaoProduto)) ?: 'Não informado') ?><small>Defeito: <?= $clientEscape(trim(strip_tags((string) $order->defeito)) ?: 'Não informado') ?></small></td><td><div class="ui-row-actions"><a class="ui-button ui-button-small" href="<?= site_url('os/visualizar/' . (int) $order->idOs) ?>">Ver OS #<?= (int) $order->idOs ?></a><?php if ($this->permission->checkPermission($role, 'eOs')) { ?><a class="ui-button ui-button-small" href="<?= site_url('os/editar/' . (int) $order->idOs) ?>">Editar OS</a><?php } ?></div></td></tr><?php } ?><?php if (! $results) { ?><tr><td colspan="5" class="ui-empty">Nenhuma OS encontrada nesta página.</td></tr><?php } ?></tbody></table></div><nav class="ui-pagination" aria-label="Paginação de ordens do cliente"><?= $this->pagination->create_links() ?></nav></div></details><?php } ?>
<?php if ($canSales) { ?><details class="ui-card ui-disclosure ui-card-following" id="tab3"><summary>Vendas <span class="ui-badge"><?= count($result_vendas) ?></span></summary><div class="ui-section-content"><div class="ui-table-scroll" role="region" aria-label="Vendas do cliente" tabindex="0"><table class="ui-table ui-history-table"><caption class="ui-sr-only">Vendas do cliente</caption><thead><tr><th scope="col">Venda</th><th scope="col">Data</th><th scope="col">Faturada</th><th scope="col">Total</th><th scope="col">Ações</th></tr></thead><tbody><?php foreach ($result_vendas as $sale) { ?><tr><td>#<?= (int) $sale->idVendas ?></td><td><?= html_escape($clientDate($sale->dataVenda)) ?></td><td><?= $sale->faturado ? 'Sim' : 'Não' ?></td><td class="ui-nowrap">R$ <?= html_escape(number_format((float) $sale->valorTotal, 2, ',', '.')) ?></td><td><div class="ui-row-actions"><a class="ui-button ui-button-small" href="<?= site_url('vendas/visualizar/' . (int) $sale->idVendas) ?>">Ver venda #<?= (int) $sale->idVendas ?></a><?php if ($this->permission->checkPermission($role, 'eVenda')) { ?><a class="ui-button ui-button-small" href="<?= site_url('vendas/editar/' . (int) $sale->idVendas) ?>">Editar venda</a><?php } ?></div></td></tr><?php } ?><?php if (! $result_vendas) { ?><tr><td class="ui-empty" colspan="5">Nenhuma venda cadastrada para este cliente.</td></tr><?php } ?></tbody></table></div></div></details><?php } ?>
</section>
<script src="<?= base_url('assets/js/client-details.js') ?>?v=1" defer></script>
